PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmName ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:Woman_Doctor dbr:Det_drønner_gjennom_dalen }

  # film name (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?film dbp:name ?filmName . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
  BIND (COALESCE(?filmName, ?filmLabel) AS ?filmName)

  # director (prefer dbp:director, fallback to dbo:director)

