SELECT ?film ?director ?birthDate
WHERE {
  VALUES ?film { dbr:Woman_Doctor dbr:Det_drønner_gjennom_dalen }

  # director (dbo or dbp)
  OPTIONAL { ?film dbo:director ?director . }
  OPTIONAL { ?film dbp:director ?director . }

  # director's birth date (dbo or dbp)
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
}
ORDER BY ?birthDate
LIMIT 1

